   await list(b,g1,true);await card(b,names.sole).getByRole("link",{name:`View details: ${names.sole}`,exact:true}).press("Enter");await a.goto(f.origin+"/group");await press(a,`Remove ${nameB}`);await press(a,"Confirm removal");await a.getByRole("status").filter({hasText:`${nameB} is now inactive`}).waitFor();await b.goBack();await b.getByRole("heading",{name:"Group access unavailable",exact:true}).waitFor();for(const suffix of["","?filter=mine"]){await b.goto(f.origin+"/watchlist"+suffix);await b.getByRole("heading",{name:"Group access unavailable",exact:true}).waitFor();check(await b.getByRole("article").count()===0,"removed account receives safe denial not empty Mine");}
   await list(a,g1,true);await card(a,names.joint).getByText("Inactive participant",{exact:false}).waitFor();await list(a,g1);await card(a,names.sole).getByText("Inactive participant",{exact:false}).waitFor();check(f.db.prepare("SELECT count(*) AS n FROM contributors WHERE title_id=?").get(joint).n===2,"creator removal preserves joint contributions");
