   const cookies=await contexts[0].cookies(),account=cookies.find(value=>value.name==="watchnext_account_session").value,legacy=cookies.find(value=>value.name==="watchnext_session").value,forged=randomBytes(32).toString("base64url");f.secrets.push(forged);
   for(const cookie of[`watchnext_account_session=${forged}; watchnext_access_mode=account`,`watchnext_account_session=${account}; watchnext_account_session=${account}; watchnext_access_mode=account`])for(const filter of["all","mine"]){const response=await fetch(f.origin+"/watchlist?filter="+filter,{headers:{cookie},signal:AbortSignal.timeout(15000)}),text=await response.text();check(text.includes("Group access unavailable")&&!text.includes(names.own)&&!text.includes(names.foreign),"forged/duplicate identity denies both filtered views");}
   const writer=new DatabaseSync(f.path);try{writer.prepare("UPDATE account_sessions SET created_at=0,expires_at=1 WHERE token_hash=?").run(credentialHash(account));}finally{writer.close();}
